window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"05hxoIszjUA","speaker":"Nasser Bourita","role":"Foreign Minister","country":"Morocco","region":"Africa","url":"https://www.youtube.com/watch?v=05hxoIszjUA","date":"20260923","title":"🇲🇦 Morocco - Foreign Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1134,"words":2239,"counts":{"claims":28,"promises":0,"attacks":2},"topics":[{"topic":"Morocco Sahara","share":0.1399,"seconds":159},{"topic":"Palestine","share":0.1292,"seconds":147},{"topic":"Terrorist groups","share":0.1202,"seconds":136},{"topic":"Morocco climate policy","share":0.1135,"seconds":129},{"topic":"Africa","share":0.0755,"seconds":86},{"topic":"Morocco autonomy","share":0.0648,"seconds":74},{"topic":"Climate change","share":0.0648,"seconds":73},{"topic":"Jerusalem","share":0.0643,"seconds":73},{"topic":"UN leadership","share":0.0634,"seconds":72},{"topic":"UNGA election","share":0.058,"seconds":66},{"topic":"International order","share":0.0555,"seconds":63},{"topic":"Morocco UN candidacy","share":0.051,"seconds":58}],"timeline":[[2,68,"UNGA election"],[69,141,"UN leadership"],[142,205,"International order"],[207,278,"Terrorist groups"],[279,344,"Terrorist groups"],[346,419,"Climate change"],[420,483,"Morocco climate policy"],[485,551,"Morocco climate policy"],[551,627,"Palestine"],[628,699,"Palestine"],[699,772,"Jerusalem"],[773,859,"Africa"],[860,928,"Morocco Sahara"],[929,1003,"Morocco autonomy"],[1005,1095,"Morocco Sahara"],[1096,1154,"Morocco UN candidacy"]],"stances":{"UNGA election":"Nasser Bourita congratulates the newly elected President of the General Assembly on behalf of Morocco.","UN leadership":"Nasser Bourita commends Secretary-General Antonio Guterres for his wisdom, consensus-building, and defense of the UN system and international law amidst global divisions.","International order":"Nasser Bourita states that the current international system is characterized by blurred standards, uncertain alliances, and a diminished capacity of regulatory structures to manage crises.","Terrorist groups":"Nasser Bourita states that non-state armed groups pose a significant and growing threat to international security, stability, and freedom of navigation.","Climate change":"Nasser Bourita argues that climate change is an immediate threat to stability and development, noting Morocco's vulnerability despite its low emissions.","Morocco climate policy":"Nasser Bourita states that Morocco has adopted a proactive water and climate policy under King Mohammed VI, setting specific emission reduction targets for 2035 and extending efforts to the African continent.","Palestine":"Nasser Bourita asserts that lasting peace in the Middle East requires an independent Palestinian state based on 1967 borders with East Jerusalem as its capital, living alongside Israel.","Jerusalem":"Morocco expresses deep concern over unilateral Israeli actions and violations of Al-Aqsa, while highlighting King Mohammed VI's efforts to preserve the city's identity and improve living conditions for its inhabitants.","Africa":"Nasser Bourita asserts that Africa is a continent of opportunity and potential, capable of solving its own challenges and contributing to global solutions, based on the vision of King Mohammed VI.","Morocco Sahara":"Nasser Bourita states that the Moroccan Sahara issue has reached a historic turning point with the adoption of Security Council resolution 2797 and is now on an irreversible course toward final settlement based on established principles.","Morocco autonomy":"Nasser Bourita asserts that the only viable solution is a political negotiation process based on Moroccan sovereignty and autonomy, rejecting the status quo and any interlocutors who violate ceasefire agreements.","Morocco UN candidacy":"Nasser Bourita presents Morocco's candidacy as a stable actor with a long diplomatic heritage contributing to the UN pillars."},"claims":[{"t":51,"quote":"I extend my sincere congratulations uh on behalf of the delegation of the Kingdom of Morocco to His Excellency Mr. Khali Rahman on his election as President of the General Assembly at its 81st session","topic":"UNGA election","kind":"fact"},{"t":78,"quote":"he assumed the leadership of our Amid the major divisions the world has experienced over the past decade, he has emerged as a voice of wisdom, consensus, and pragmatism","topic":"UN leadership","kind":"fact"},{"t":91,"quote":"defending tirelessly and courageously the United Nations system and international law as the two fundamental pillars for the maintenance of international peace and security","topic":"UN leadership","kind":"fact"},{"t":146,"quote":"Alliances have become open question. International law is frequently And its capacity to regulate international relations faces numerous End of quote from his majesty the king.","topic":"International order","kind":"fact"},{"t":170,"quote":"First, the escalation of acute and diverse international crises, military, economic, energy-related, and environmental.","topic":"International order","kind":"fact"},{"t":258,"quote":"At the global level, more than 200 million people live in areas under the control of armed groups or in contested","topic":"Terrorist groups","kind":"number"},{"t":269,"quote":"Moreover, more than 130 non-state armed groups have been identified as legally classified parties to armed conflicts.","topic":"Terrorist groups","kind":"number"},{"t":279,"quote":"These figures clearly reflect the scale of the spread and proliferation of these groups in a world that over the past two decades has become less secure and less stable.","topic":"Terrorist groups","kind":"fact"},{"t":295,"quote":"Further, the close links between these armed groups and separatist militias on the one hand and terrorist organizations and criminal networks, as well as mercenary elements on the other hand, are evident to all.","topic":"Terrorist groups","kind":"fact"},{"t":410,"quote":"Despite its limited contribution to greenhouse gas emissions, Morocco remains among the countries most vulnerable to the impacts of climate change.","topic":"Climate change","kind":"fact"},{"t":452,"quote":"the kingdom has set for the period of 2026-2035 a target of reducing greenhouse gas emissions by up to 53% by 2035","topic":"Morocco climate policy","kind":"number"},{"t":485,"quote":"The royal initiative to establish three African climate commissions for the Congo Basin the Sahel region and the African island states has generated promising momentum","topic":"Morocco climate policy","kind":"fact"},{"t":560,"quote":"the establishment of a lasting peace in the Middle East depends on the establishment of an independent, sovereign, and viable Palestinian state on the borders of the 4th of June 1967 with East Jerusalem as its capital living side by side with a state of Israel in peace and security.","topic":"Palestine","kind":"fact"},{"t":586,"quote":"the kingdom renews its call for respect for the ceasefire in Gaza and for the entry of humanitarian assistance into the strip in sufficient quantities without impediment or interruption.","topic":"Palestine","kind":"fact"},{"t":649,"quote":"contributing to the training of the Palestinian police, deploying high-ranking military officers to the internal security forces, and setting up a military field hospital","topic":"Palestine","kind":"fact"},{"t":670,"quote":"adoption of certain laws that affect the legal status of Palestinian territory and pave the way for their seizure for the purpose of settlement expansion","topic":"Palestine","kind":"fact"},{"t":707,"quote":"repeated violations of the sanctity of Al-Aqsa Mosque, which constitutes serious transgressions that contribute to fueling the discourse of extremism and hatred","topic":"Jerusalem","kind":"fact"},{"t":725,"quote":"His Majesty King Mohammed VI, may God assist him, continues his work to preserve the historical, cultural, and spiritual identity of the holy city and its legal status","topic":"Jerusalem","kind":"self_credit"},{"t":796,"quote":"Africa must trust Africa.","topic":"Africa","kind":"fact"},{"t":879,"quote":"the question of the Moroccan Sahara reached a historic turning point with the adoption by the Security Council of resolution 2797 last October.","topic":"Morocco Sahara","kind":"fact"},{"t":936,"quote":"there is no solution outside the framework of the autonomy under Moroccan sovereignty.","topic":"Morocco autonomy","kind":"fact"},{"t":962,"quote":"the responsibility and obligations of the four parties clearly identified by Security Council resolution 2797.","topic":"Morocco autonomy","kind":"fact"},{"t":992,"quote":"continued holding of the population of the camps as hostages for a half a century in flagrant violation of international law and international humanitarian law.","topic":"Morocco autonomy","kind":"fact"},{"t":1013,"quote":"the Kingdom of Morocco steadfastly continues to drive social and economic development in its southern provinces, particularly in areas of infrastructure, university health sector, and airports","topic":"Morocco Sahara","kind":"fact"},{"t":1033,"quote":"tomorrow, God willing, the inhabitants of these Saharan provinces will fulfill their national and political duty by participating as they have always done in the past in the legislative elections of the kingdom","topic":"Morocco Sahara","kind":"fact"},{"t":1083,"quote":"the Kingdom of Morocco has presented its candidacy for a non-permanent seat on the Security Council for the term 2028-2029","topic":"Morocco Sahara","kind":"fact"},{"t":1108,"quote":"It is the candidacy of a kingdom with a diplomatic heritage spanning several centuries, which carries the vision of His Majesty King Mohammed VI","topic":"Morocco UN candidacy","kind":"fact"},{"t":1127,"quote":"This candidacy also reflects the continued contribution of the Kingdom of Morocco to the three pillars of the United Nations, namely peace, development, and the rule of law.","topic":"Morocco UN candidacy","kind":"fact"}],"promises":[],"attacks":[{"t":335,"quote":"And responsibility must be assigned to the states that sponsor, harbor, finance, and arm them and provide them with safe haven and support.","topic":"Terrorist groups","target":"State sponsors of terrorism"},{"t":992,"quote":"continued holding of the population of the camps as hostages for a half a century in flagrant violation of international law and international humanitarian law.","topic":"Morocco autonomy","target":"Detaining authorities"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":2,"topic":"UNGA election","text":"I now give the floor to His Excellency Nasser Bourita, Minister of Foreign Affairs, African Cooperation, and Moroccans Abroad of &gt;&gt; Mr. President of the General Assembly &gt;&gt; Your Excellency, President of the General Assembly, Mr. Secretary-General, Your Excellencies, ladies and gentlemen, I extend my sincere congratulations uh on behalf of the delegation of the Kingdom of Morocco to His Excellency Mr. Khali Rahman on his election as President of the General Assembly at its 81st session, and I wish him every success in his lofty mission."},{"t":69,"topic":"UN leadership","text":"I also commend the tireless efforts of Secretary-General Antonio Guterres he assumed the leadership of our Amid the major divisions the world has experienced over the past decade, he has emerged as a voice of wisdom, consensus, and pragmatism, defending tirelessly and courageously the United Nations system and international law as the two fundamental pillars for the maintenance of international peace and security. Mr. Guterres has remained a symbol of multilateral diplomacy and of international cooperation in overcoming the turmoil and obstacles facing our world today. Mr. President, the most apt description of our international reality is the one expressed by his majesty King Mohammed may God assist him, when his majesty said and I quote, \"The world is changing at an unprecedented pace and certainties are steadily receding."},{"t":142,"topic":"International order","text":"This has led to a blurring of standards and concepts. Alliances have become open question. International law is frequently And its capacity to regulate international relations faces numerous End of quote from his majesty the king. We are therefore facing a world whose fundamental features are the following. First, the escalation of acute and diverse international crises, military, economic, energy-related, and environmental. Second, the spread of confrontational tendencies as a key determinant of relations between states. Third, the difficulty of predicting the outcome of crises. We know when they begin, but not when they will end. Fourth, the diminishing capacity of existing regulatory structures to play the role in preventing and managing crises."},{"t":207,"topic":"Terrorist groups","text":"In this complex international context, Mr. President, I wish to focus on three to which the international community must accord priority. First, confronting non-state armed groups as a threat to international security and stability. addressing climate change and its effects. Third, tackling regional challenges, particularly in the Middle East and The role of non-state armed groups that threaten the security and stability of states has grown considerably. Indeed, they now seek to control maritime corridors and straits and to threaten freedom of navigation. They also target facilities in a number of countries. At the global level, more than 200 million people live in areas under the control of armed groups or in contested Moreover, more than 130 non-state armed groups have been identified as legally classified parties to armed conflicts."},{"t":279,"topic":"Terrorist groups","text":"These figures clearly reflect the scale of the spread and proliferation of these groups in a world that over the past two decades has become less secure and less stable. Further, the close links between these armed groups and separatist militias on the one hand and terrorist organizations and criminal networks, as well as mercenary elements on the other hand, are evident to all. It is therefore a mistake to believe that some of these groups are peaceful or constructive or that they can engage in the settlement of conflicts. All these groups use violence to impose a fait accompli and to serve the agenda of those who control They must therefore be dealt with And responsibility must be assigned to the states that sponsor, harbor, finance, and arm them and provide them with safe haven and support."},{"t":346,"topic":"Climate change","text":"The responsibility of these sponsoring states is not merely political. It is also legal, moral, and historical. These groups and their sponsors alike cannot be allowed to become a means of evading responsibility or a tool for carrying out what states cannot do deterrent sanctions must be imposed on these groups and their All those who provide them with support, financing, or arms must be held accountable. Mr. President, there can be no way to sustain peace and development without effectively addressing the challenge of climate change, which is no longer a future threat. It is already affecting water and food as well as the stability of territories, economies, and the living conditions of Despite its limited contribution to greenhouse gas emissions, Morocco remains among the countries most vulnerable to the impacts of climate change."},{"t":420,"topic":"Morocco climate policy","text":"Accordingly, in line with the vision of His Majesty King Mohammed the VI, may God assist him, the kingdom has adopted a proactive policy based on the continued construction of dams, the interconnection of water basins, seawater desalination, the reuse of treated wastewater, and the rationalization of water resource management, particularly in the agricultural sector. This national effort forms part of an international commitment to climate action. On that basis, the kingdom has set for the period of 2026-2035 a target of reducing greenhouse gas emissions by up to 53% by 2035 while placing adaptation and strengthening of territorial at the top of its priorities. This effort has extended to the African continent which suffers from the devastating effects of climate change."},{"t":485,"topic":"Morocco climate policy","text":"The royal initiative to establish three African climate commissions for the Congo Basin the Sahel region and the African island states has generated promising momentum to strengthen African climate action and coordination among the states of the continent in addressing these challenges. However, addressing climate change cannot rely on national effort alone. It requires the provision of affordable and accessible financing technology transfer and genuine international solidarity enabling developing countries to fulfill their responsibilities towards present and future generations alike. Mr. President Madam President, the Palestinian question remains a constant priority in the foreign policy of the Kingdom of Morocco based on its belief in the justice of this that this is a just cause and it's central to achieving peace and stability in the Middle East region."},{"t":551,"topic":"Palestine","text":"Building on this conviction the Kingdom of Morocco under the leadership of His Majesty King Mohammed the VI believes that the establishment of a lasting peace in the Middle East depends on the establishment of an independent, sovereign, and viable Palestinian state on the borders of the 4th of June 1967 with East Jerusalem as its capital living side by side with a state of Israel in peace and security. In the face of the tragedy that the brotherly Palestinian people continue to endure, the kingdom renews its call for respect for the ceasefire in Gaza and for the entry of humanitarian assistance into the strip in sufficient quantities without impediment or interruption. At the same time, Morocco stresses the need to support the Palestinian Authority, particularly in the financial, technical, structural, humanitarian, and training fields, and to accompany the reforms it is undertaking within its various Morocco also renews its support for the pivotal role of the United Nations Relief and Works Agency for Palestine refugees in the Near East, UNRWA."},{"t":628,"topic":"Palestine","text":"In keeping with its approach of supporting initiatives aimed at achieving peace in the Middle East, Morocco has decided to participate in the international stabilization force in and to contribute through humanitarian and security initiatives to establishing a climate of peace and security in the region by contributing to the training of the Palestinian police, deploying high-ranking military officers to the internal security forces, and setting up a military field hospital in addition to its readiness to lead a program to counter extremism. Developments in the West Bank are deeply alarming, including the adoption of certain laws that affect the legal status of Palestinian territory and pave the way for their seizure for the purpose of settlement expansion, as well as the systematic violence perpetrated by Israeli settlers against Palestinian All these measures point in one direction, the displacement of the population, and the undermining of the material bases for the establishment of an independent Palestinian state."},{"t":699,"topic":"Jerusalem","text":"With regard to the city of Jerusalem, Morocco expresses its deep concern about unilateral Israeli and the repeated violations of the sanctity of Al-Aqsa Mosque, which constitutes serious transgressions that contribute to fueling the discourse of extremism and hatred at the expense of the voice of wisdom and moderation. As the chair of Al-Quds Committee, His Majesty King Mohammed VI, may God assist him, continues his work to preserve the historical, cultural, and spiritual identity of the holy city and its legal status, as well as to improve the living conditions of the Maghdisi inhabitants, political and diplomatic action with programs implemented on the ground by Bayt Mal Al-Quds Al-Sharif agency, the executive arm of Al-Quds Committee. Mr. President, despite its significant human, natural, and civilizational assets, the African continent faces a gap between the scale of the commitments announced for its benefit by the international community and the value of what has actually been achieved on the ground."},{"t":773,"topic":"Africa","text":"Contrary to the stereotypical image held by some, Africa is not a continent of conflicts and a hotbed of problems. Rather, it is a land of opportunity and potential, capable of devising solutions and putting forward That is the idea summed up by His Majesty King Mohammed VI, may God assist him, in his eloquent words, \"Africa must trust Africa.\" End of quote. The enlightened royal vision for Africa, which has materialized through a significant number of projects, stems from a firm conviction that the continent has attained a level of maturity that qualifies it to participate effectively in all decisions relating to its affairs. Indeed, it is capable of contributing to formulating proposals and solutions to the challenges facing the world as a Morocco has translated this vision into practical and tangible royal The most prominent of which are perhaps the royal initiative to enable Sahel states to access the Atlantic Ocean, as well as the African Atlantic states the African Atlantic gas pipeline project, as well as investments in regional infrastructure, cooperation in the areas of food security, fertilizer production, and training programs for African executives."},{"t":860,"topic":"Morocco Sahara","text":"This is in addition to partnerships in the areas of health, renewable energy, and water resource Madam President, with regard to the North African region, thanks to the momentum initiated by His Majesty King Mohammed VI, may God assist him, the question of the Moroccan Sahara reached a historic turning point with the adoption by the Security Council of resolution 2797 last October. Since then, this regional dispute has embarked on an irreversible course, breaking with the past and looking to the future with a view to its final settlement. This track rests on principles and parameters that admit no interpretation nor any reading between the lines or in the margins, as some are vainly deluding themselves in flagrant denial of reality and total disregard for established truth."},{"t":929,"topic":"Morocco autonomy","text":"These principles, as set forth in this critical resolution, are as follows. First, there is no solution outside the framework of the autonomy under Moroccan sovereignty. Second, there is no approach or mechanism other than the political negotiation process under the auspices of the United Nations and on a sole basis, namely the autonomy presented by the Kingdom of Morocco. there can be no discussion or dispute regarding the responsibility and obligations of the four parties clearly identified by Security Council resolution 2797. Fourth, there will be no maintaining of the status quo preferred by the other The train of political solution has already departed. Fifth, there is no credibility for interlocutors who violate the ceasefire and refuse to respect Security Council resolutions. Sixth and last, there can be no tolerance for the continued holding of the population of the camps as hostages for a half a century in flagrant violation of international law and international humanitarian law."},{"t":1005,"topic":"Morocco Sahara","text":"Alongside with its firm commitment to the final settlement of this regional affected regional dispute, the Kingdom of Morocco steadfastly continues to drive social and economic development in its southern provinces, particularly in areas of infrastructure, university health sector, and airports, among It is a fortunate coincidence tomorrow, God willing, the inhabitants of these Saharan provinces will fulfill their national and political duty by participating as they have always done in the past in the legislative elections of the kingdom. In so doing, they will strengthen democratic representation and contribute to the day-to-day management of the needs of the inhabitants of the Moroccan provinces. Madam President, the Kingdom of Morocco, true to its constant approach, is determined to contribute effectively and responsibly to the maintenance of international peace and This is done in accordance with a realistic vision of international cooperation grounded in solidarity and with full respect for international law, national sovereignty, and territorial It is in this context that the Kingdom of Morocco has presented its candidacy for a non-permanent seat on the Security Council for the term 2028-2029, so that it may continue to serve peace,"},{"t":1096,"topic":"Morocco UN candidacy","text":"collective security, and multilateralism with full respect for the purposes and principles enshrined in the Charter of the United Nations. It is the candidacy of a kingdom with a diplomatic heritage spanning several centuries, which carries the vision of His Majesty King Mohammed VI, may God assist him, as an actor for stability, as an anchor for stability, and sustainable development in the This candidacy also reflects the continued contribution of the Kingdom of Morocco to the three pillars of the United Nations, namely peace, development, and the rule of law. I thank you. &gt;&gt; I thank the Minister of Foreign Affairs, African Cooperation, and Moroccans Abroad of Morocco."}],"compare":[{"topic":"Israel–Palestine","share":0.1935,"mean":0.0517,"rank":11,"others":76},{"topic":"UN & its reform","share":0.1214,"mean":0.2052,"rank":133,"others":170},{"topic":"Terrorism","share":0.1202,"mean":0.0023,"rank":1,"others":6},{"topic":"Africa","share":0.0755,"mean":0.0232,"rank":27,"others":36},{"topic":"Climate Change","share":0.0648,"mean":0.0427,"rank":52,"others":77},{"topic":"International Law & Order","share":0.0555,"mean":0.0604,"rank":80,"others":102}]};
